import { pathToFileURL } from "node:url";

import {
  canonicalPath,
  editPaths,
  readHookInput,
  shellCommand,
  shellWriteTargets,
} from "#scripts/lib/agent-hook";

import type { HookInput } from "#scripts/lib/agent-hook";

/**
 * Shared PreToolUse hook: refuse agent edits on guarded paths.
 *
 * `src/lib/data/tracker-data.json` is generated by the pipeline (AGENTS.md, architecture
 * boundaries). The pipeline command is allowed; the hook checks direct tool paths, patch headers,
 * & shell write targets. Exit code 2 blocks the call and feeds stderr back to the agent.
 * `src/lib/components/ui/` began as vendored shadcn-svelte code but is project-owned & editable.
 * `docs/superpowers/` holds historical plans & specs (AGENTS.md, architecture boundaries).
 */

const GUARDED_PATHS = [
  {
    advice:
      "src/lib/data/tracker-data.json is generated. Regenerate it with `pnpm run pipeline -- <assets path>` instead of editing it.",
    pattern: /(^|\/)src\/lib\/data\/tracker-data\.json$/,
  },
  {
    advice:
      "docs/superpowers/ holds historical plans & specs. Update the current docs/*.md instead.",
    pattern: /(^|\/)docs\/superpowers\//,
  },
];

/** Returns the refusal message when the tool call targets a guarded path, else undefined. */
export function guardMessage(input: HookInput): string | undefined {
  const command = shellCommand(input);
  let targets = editPaths(input);
  if (command !== undefined) {
    targets = shellWriteTargets(command);
  }
  for (const target of targets) {
    const absolute = canonicalPath(input.cwd ?? process.cwd(), target).replaceAll("\\", "/");
    const guarded = GUARDED_PATHS.find(({ pattern }) => pattern.test(absolute));
    if (guarded) {
      return `Blocked edit of ${target}. ${guarded.advice}`;
    }
  }
  return undefined;
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const message = guardMessage(readHookInput());
  if (message !== undefined) {
    console.error(message);
    process.exitCode = 2;
  }
}
